mapper.select:
SELECT id FROM scm_price_adjust
WHERE status = #{status} AND effective_time IS NOT NULL AND effective_time <= #{now}
ORDER BY effective_time, id

SELECT h.*, a.adjust_no, s.code AS scheme_code, s.name AS scheme_name,
       m.code AS material_code, m.name AS material_name, m.spec
FROM scm_price_history h
JOIN scm_price_adjust a ON a.id = h.adjust_id
JOIN wms_material m ON m.id = h.material_id
LEFT JOIN scm_price_scheme s ON s.id = h.scheme_id

    h.material_id = #{materialId}
    AND h.scheme_id = #{schemeId}
    AND h.target = #{target}
    AND h.adjust_id = #{adjustId}

ORDER BY h.effect_time DESC, h.id DESC
